function longestConsecutive(root) {
  let best = 0;

  function dfs(node, parent, length) {
    if (!node) {
      return;
    }
    if (parent && node.val === parent.val + 1) {
      length++;
    } else {
      length = 1;
    }
    best = Math.max(best, length);
    dfs(node.left, node, length);
    dfs(node.right, node, length);
  }

  dfs(root, null, 0);
  return best;
}

