function longestConsecutive(root) {
  // For every node, walk up through parents while each step goes down in value by exactly one.
  const parentOf = new Map();
  const all = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    all.push(node);
    for (const child of [node.left, node.right]) {
      if (child) {
        parentOf.set(child, node);
        stack.push(child);
      }
    }
  }
  let best = 0;
  for (const node of all) {
    let count = 1;
    let current = node;
    while (parentOf.has(current) && parentOf.get(current).val === current.val - 1) {
      current = parentOf.get(current);
      count++;
    }
    best = Math.max(best, count);
  }
  return best;
}

