function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const limit = 30000;
  const clamp = v => Math.max(-limit, Math.min(limit, v));
  const count = size === 'large' ? 900 + pick(100) : 1 + pick(12);
  const edge = size === 'large' && rand() < 0.3;
  const base = edge ? (rand() < 0.5 ? limit - pick(50) : -limit + pick(50)) : size === 'large' ? pick(2 * limit + 1) - limit : pick(11) - 5;
  const stepUp = rand() * 0.5 + 0.3;
  const childValue = parentVal => {
    const r = rand();
    if (r < stepUp) return clamp(parentVal + 1);
    if (r < stepUp + 0.15) return clamp(parentVal - 1);
    if (r < stepUp + 0.25) return parentVal;
    return size === 'large' ? clamp(parentVal + pick(201) - 100) : pick(11) - 5;
  };
  const deep = rand() < 0.35;
  const nodes = [{ val: base, left: null, right: null }];
  while (nodes.length < count) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: childValue(parent.val), left: null, right: null };
    parent[side] = node;
    nodes.push(node);
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
